import{_ as t,b as o,a as s}from"./chunks/run-live.BHkhzNf5.js";import{_ as r}from"./chunks/diagnostics.v07UOWJq.js";import{_ as a}from"./chunks/report.BOAPNauD.js";import{_ as n,o as i,c as d,a2 as h}from"./chunks/framework.C1aUlgNS.js";const l="/Jevwright/guide/screenshots/workspace-layout.webp",c="/Jevwright/guide/screenshots/editor-header.webp",T=JSON.parse('{"title":"The web workspace","description":"","frontmatter":{},"headers":[],"relativePath":"guide/workspace.md","filePath":"guide/workspace.md"}'),p={name:"guide/workspace.md"};function u(g,e,f,m,w,b){return i(),d("div",null,[...e[0]||(e[0]=[h('<h1 id="the-web-workspace" tabindex="-1">The web workspace <a class="header-anchor" href="#the-web-workspace" aria-label="Permalink to &quot;The web workspace&quot;">​</a></h1><p>The workspace is where you keep, edit and run your test files. It looks like a code editor: the sidebar on the left (1), the editor in the middle (2), and two consoles on the right, the <strong>Debug console</strong> (3) above the <strong>Output console</strong> (4) with the file&#39;s <strong>History</strong> (5). The status bar (6) runs along the bottom.</p><p><img src="'+l+'" alt="The workspace with a test file open, with markers on the sidebar (1), the editor (2), the Debug console (3), the Output console (4), History (5) and the status bar (6)"></p><h2 id="projects-folders-and-test-files" tabindex="-1">Projects, folders and test files <a class="header-anchor" href="#projects-folders-and-test-files" aria-label="Permalink to &quot;Projects, folders and test files&quot;">​</a></h2><p>The sidebar lists your <strong>Projects</strong>. A Project is a top-level folder, usually one per app you test, and holds your test files directly or in <strong>folders</strong>. Folders can hold folders, up to 4 levels counting the Project.</p><p><img src="'+t+'" alt="The sidebar with markers on the + next to Projects (1), the menu of a folder&#39;s + with New folder, New test file and Upload files… (2), and the status icons of a passed file (3) and a failed file (4)"></p><table tabindex="0"><thead><tr><th>In the sidebar</th><th>What it does</th></tr></thead><tbody><tr><td><strong>+</strong> next to &quot;Projects&quot; (1)</td><td>Adds a Project; type its name in place and press Enter</td></tr><tr><td><strong>+</strong> on a Project or folder</td><td>Opens a menu (2) with <strong>New folder</strong>, <strong>New test file</strong>, and <strong>Upload files…</strong></td></tr><tr><td>The key icon on a Project&#39;s row</td><td>Opens the Project&#39;s Variables</td></tr><tr><td>Drag and drop</td><td>Moves a folder or test file to another Project or folder. Dropping <code>.yaml</code> files or folders from your computer imports them</td></tr><tr><td><strong>Rename</strong>, <strong>Delete</strong>, <strong>Move to…</strong></td><td>On every row; F2 renames the focused row</td></tr><tr><td>The icon in front of a file</td><td>The latest Run: passed (3), failed (4), running, or never run (a dashed circle)</td></tr></tbody></table><p>Names of Projects and folders can be up to 100 characters. Test file names use only letters, digits, <code>-</code>, <code>_</code> and <code>.</code>, and end in <code>.yaml</code>. Uploading never overwrites a file: one whose name is taken is skipped with the reason.</p><p>A file&#39;s Runs stay with it when you rename or move it. Deleting a file deletes its history; a new file with the same name starts fresh.</p><p>The workspace&#39;s home page lists every test file with the status of its latest Run.</p><h2 id="the-editor" tabindex="-1">The editor <a class="header-anchor" href="#the-editor" aria-label="Permalink to &quot;The editor&quot;">​</a></h2><p>A test file opens in the editor, with YAML highlighting and line numbers. The badge next to the file name (1) says whether it is <strong>Saved</strong> or <strong>Unsaved</strong>, and how its latest Run ended.</p><p><img src="'+c+'" alt="The editor&#39;s header, with markers on the file&#39;s badge &quot;Passed&quot; (1), Save (2), Run (3) and the button that hides the consoles (4)"></p><table tabindex="0"><thead><tr><th>Do</th><th>How</th></tr></thead><tbody><tr><td>Save</td><td><strong>Save</strong> (2) or <code>Ctrl+S</code> (<code>Cmd+S</code> on a Mac)</td></tr><tr><td>Run</td><td><strong>Run</strong> (3) or <code>Ctrl+Enter</code>; unsaved changes are saved first</td></tr><tr><td>Hide or show the consoles</td><td>The button at the top right (4), or the same button at the right of the status bar</td></tr><tr><td>Jump to a problem</td><td>Click it in the Debug console</td></tr></tbody></table><p>The file is checked as you type and when you save. Each problem is underlined on its line, with the message on hover.</p><h2 id="the-debug-console" tabindex="-1">The Debug console <a class="header-anchor" href="#the-debug-console" aria-label="Permalink to &quot;The Debug console&quot;">​</a></h2><p>The <strong>Debug console</strong>, at the top right, lists the file&#39;s problems, one line each (2): <code>Line &lt;line&gt;: &lt;message&gt;</code> and the problem&#39;s code, such as <code>E005</code>. The editor underlines each of those lines (1).</p><p><img src="'+r+'" alt="A file with seven problems, with markers on the underlined line 5 in the editor (1) and its problem at the top of the Debug console (2)"></p><p>&quot;No problems&quot; means the file is valid. A file with problems cannot run: <strong>Run</strong> answers with the problems instead. The <a href="./../reference/diagnostics.html">Diagnostics</a> page explains every code and how to fix it.</p><p>When an agent wrote the file, copy the Debug console&#39;s lines and paste them back to the agent to fix.</p><h2 id="the-output-console-and-runs" tabindex="-1">The Output console and Runs <a class="header-anchor" href="#the-output-console-and-runs" aria-label="Permalink to &quot;The Output console and Runs&quot;">​</a></h2><p>The <strong>Output console</strong>, below the Debug console, follows the current Run live: its status (1), how many steps passed, and one line per step with its status: <strong>Passed</strong> (2), <strong>Running</strong> (3), <strong>Pending</strong> (4) or <strong>Failed</strong>, with the reason of a failed step. Below it, <strong>History</strong> lists the file&#39;s Runs, newest first.</p><p><img src="'+o+'" alt="The Output console during a Run, with markers on the Running badge (1), the passed step 1 (2), the running step 2 (3) and the pending steps 3 to 8 (4)"></p><p>Each console opens and collapses on its own from its header, and the toggle in the header or the status bar hides the whole column, so the editor takes the full width.</p><h2 id="reports" tabindex="-1">Reports <a class="header-anchor" href="#reports" aria-label="Permalink to &quot;Reports&quot;">​</a></h2><p><strong>Open run details</strong>, or a Run in History, opens the report beside the editor; <strong>Open full page</strong> (2) opens it on its own page. A report shows:</p><p><img src="'+a+'" alt="A report beside the editor, with markers on the status (1), Open full page (2), Download report (3), the screenshot of step 1 (4) and the locate method &quot;selector&quot; of step 2 (5)"></p><ul><li>the Run&#39;s status, when it started, its duration, and how many steps passed (1);</li><li>every step, with its action, its line in the file, its status and duration, how its element was found (<code>selector</code>, <code>visual</code> or <code>dom</code>) (5), and the reason when it failed;</li><li>a screenshot of the page after each step (4); click it to see it full size;</li><li><strong>Source when it ran</strong>: the file as it was when the Run started, since you may have edited it since;</li><li><strong>Download report</strong> (3), the report as JSON, and <strong>Download trace</strong>, a Playwright trace. Open the trace at <a href="https://trace.playwright.dev" target="_blank" rel="noreferrer">trace.playwright.dev</a> to step through the Run with the page, its network requests and its console.</li></ul><p>A Run stops at its first failed step; the steps after it stay <strong>Pending</strong>.</p><h2 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to &quot;Variables&quot;">​</a></h2><p>A Variable is a named value that test files use as <code>{{NAME}}</code>, such as <code>baseUrl: &quot;{{BASE}}&quot;</code> or <code>value: &quot;{{APP_PASSWORD}}&quot;</code>. Variables belong to a Project; every test file in the Project, in any folder, uses them.</p><p>Click the key icon on a Project&#39;s row in the sidebar to open its Variables. Each Variable is one row (1); its value is hidden as <code>****</code> until you click the eye button (2). To add a Variable, or to change one, type its <strong>Name</strong> (3) and <strong>Value</strong> (4) and click <strong>Save</strong> (5); saving a name that exists replaces its value. <strong>Delete</strong> next to a Variable removes it. Names use capital letters, digits and <code>_</code>, and do not start with a digit.</p><p><img src="'+s+'" alt="The Variables page of the Quick Start project, with markers on the row of BASE (1), its eye button (2), the Name field (3), the Value field (4) and Save (5)"></p><p>When a Run starts, every <code>{{NAME}}</code> in the file is replaced with the Variable&#39;s value. A Variable the Project does not have fails the step that uses it with <code>Variable {{NAME}} is not set</code>. Values are hidden in reports and failure reasons, which show <code>{{NAME}}</code> instead.</p><h2 id="themes" tabindex="-1">Themes <a class="header-anchor" href="#themes" aria-label="Permalink to &quot;Themes&quot;">​</a></h2><p>The workspace follows your system&#39;s light or dark setting. The theme switch next to your account, at the bottom of the sidebar, picks <strong>Light</strong>, <strong>Dark</strong> or <strong>System</strong>.</p>',36)])])}const P=n(p,[["render",u]]);export{T as __pageData,P as default};
